import{_ as r,l as s,o as e,c as d,v as o,p as c,x as t,d as i,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"拥塞控制","description":"","frontmatter":{"title":"拥塞控制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcp-congestion.md","filePath":"cs/tcp-congestion.md","lastUpdated":1789023840000}'),h={name:"cs/tcp-congestion.md"};function A(C,a,_,E,m,u){const n=s("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="拥塞控制" tabindex="-1">拥塞控制 <a class="header-anchor" href="#拥塞控制" aria-label="Permalink to &quot;拥塞控制&quot;">​</a></h1><div class="epigraph"><p>网络自己的队列也会满；发送方必须根据丢包或延迟减小飞行数据，否则重传会加剧拥塞。</p><footer>—— 据 Jacobson, Congestion Avoidance and Control, SIGCOMM 1988；RFC 5681 整理</footer></div><p><a href="/cs/nagle-delayed-ack">上一课</a>用 rwnd 保护对端。路由器缓冲不是 rwnd 的一部分：多条连接共享瓶颈时，人人按 rwnd 发仍会丢。<a href="/cs/udp">UDP</a> 不管这件事。缺口是 <strong>TCP 拥塞控制</strong>：慢启动、拥塞避免、AIMD，用 <code>cwnd</code>。本课不把每一种 CUBIC 曲线写成标准正文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1980 年代拥塞崩溃：丢包导致重传，重传增加负载。Jacobson：把丢包当信号，指数增大探测带宽（慢启动），线性探测（拥塞避免），丢则减半（乘法减小）。缺口不是再定义序号，而是飞行字节的第二条上限 <code>min(cwnd, rwnd)</code>。</p><p>本课以丢包信号为主；延迟信号（BBR 等）作边界对照。</p><p><span class="marginnote">AIMD：加性增、乘性减，多流共享瓶颈时有利于公平收敛（Chiu–Jain 直觉）。快重传可配快恢复，避免慢启动回退到 1。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>新连接：<code>cwnd</code> 从初始窗口指数增，直到丢或到 <code>ssthresh</code>。拥塞避免：每 RTT 大约加一 MSS。超时：<code>ssthresh</code> 记下飞行的一半，<code>cwnd</code> 回退。三个重复 ACK：快重传，进入快恢复。与<a href="/cs/timeslice-cfs">公平调度</a>类比：都是份额，但这里没有中央 CFS，信号是隐式的丢包。</p>',9)),(e(),c(p,null,{default:t(()=>[l(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SS%5B%22%E6%85%A2%E5%90%AF%E5%8A%A8%3A%20%E6%8C%87%E6%95%B0%22%5D%20--%3E%20CA%5B%22%E6%8B%A5%E5%A1%9E%E9%81%BF%E5%85%8D%3A%20%E7%BA%BF%E6%80%A7%22%5D%0A%20%20CA%20--%3E%20LOSS%5B%22%E4%B8%A2%E5%8C%85%22%5D%0A%20%20LOSS%20--%3E%20HALVE%5B%22cwnd%20%E5%87%8F%E5%8D%8A%22%5D%0A%20%20HALVE%20--%3E%20CA%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>拥塞控制是<a href="/cs/layering-e2e">端到端论证</a>的实例：瓶颈队列在中间，端根据反馈调速，而不要求每台路由器为每流保留完整状态（与 ATM 式预留对照）。路由器可加 AQM/ECN 把信号显式化，本课不把 RED 参数调完。UDP 实时流若不节制，会挤占遵守 AIMD 的 TCP——政策问题点名。</p><p>与磁盘电梯不同：这里没有全局请求队列排序，只有分布式加减。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 RFC 9438 CUBIC 的窗口公式当必推导。不引入数据中心 DCTCP 的全部标记逻辑。多路径 TCP 不进主干。下一课 QUIC 把拥塞做到用户态 UDP 上，并对照握手。</p><p>ECN 把丢包信号换成显式标记，避免真的排队溢出。部署取决于路径上的路由器，端必须协商能力。</p><p>后课默认：TCP 飞行数据受 cwnd 与 rwnd 双重限制。把可靠与加密搬到 UDP 上的另一种栈，下一课 QUIC 对照。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>丢包（或标记）驱动 cwnd；慢启动与 AIMD 避免拥塞崩溃。</li><li>与 rwnd 分工：网络 vs 对端。</li><li>QUIC 在 UDP 上复用这些思想，下一课。</li><li>出处：Jacobson, 1988；RFC 5681；Kurose and Ross。</li></ul>',9))])}const P=r(h,[["render",A]]);export{T as __pageData,P as default};
